// Acceptance tests for lane cob-d (plan Tasks 8–9). Written by the orchestrator before dispatch.
// They go through the package entry point '@cob/core' and drive real git against a local bare remote.
// Do not edit this file; add your own tests in the per-module test files.
import { beforeEach, expect, test } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import {
  DataRepo,
  SecretLeakError,
  cloneDataRepo,
  createCommand,
  finishCommand,
  git,
  initDataLayout,
  initPrivateRepo,
  pullRepo,
  queuedCommands,
  syncRepo,
  type Application,
  type Source,
} from '@cob/core';

const T0 = '2026-11-11T09:00:00.000Z';
const identity = { name: 'Test User', email: 'test@example.com' };
const LONG = 30_000;

const tmp = (prefix: string) => fs.mkdtempSync(path.join(os.tmpdir(), prefix));
const sh = (cwd: string, ...args: string[]) => execFileSync('git', args, { cwd }).toString();
const rebaseInProgress = (d: string) =>
  fs.existsSync(path.join(d, '.git', 'rebase-merge')) || fs.existsSync(path.join(d, '.git', 'rebase-apply'));
const settled = (d: string) => {
  expect(rebaseInProgress(d)).toBe(false);
  expect(sh(d, 'status', '--porcelain')).toBe('');
};
const writeRaw = (d: string, rel: string, value: unknown) =>
  fs.writeFileSync(path.join(d, rel), JSON.stringify(value, null, 2) + '\n');

const source = (o: Partial<Source> = {}): Source => ({
  id: 's1',
  url: 'https://careers.example.com/jobs',
  label: 'original',
  enabled: true,
  addedAt: T0,
  addedBy: 'user',
  ...o,
});
const application = (o: Partial<Application> = {}): Application => ({
  id: 'a1',
  organization: 'Example Foods',
  title: 'original',
  link: 'https://careers.example.com/jobs/1',
  state: 'parked',
  pendingSubmission: null,
  park: { type: 'captcha', at: T0 },
  parkHistory: [{ type: 'captcha', at: T0 }],
  submission: null,
  skip: null,
  statusNotes: [],
  closedAt: null,
  createdAt: T0,
  updatedAt: T0,
  ...o,
});

let remote: string;
let appDir: string;
let agentDir: string;
let app: DataRepo;
let agent: DataRepo;

beforeEach(async () => {
  remote = path.join(tmp('cob-remote-'), 'remote.git');
  execFileSync('git', ['init', '-q', '--bare', '-b', 'main', remote]);
  appDir = path.join(tmp('cob-app-'), 'repo');
  fs.mkdirSync(appDir);
  agentDir = path.join(tmp('cob-agent-'), 'repo');
  await initPrivateRepo(appDir, { identity, remote });
  await cloneDataRepo(remote, agentDir, identity);
  app = new DataRepo(appDir, 'app');
  agent = new DataRepo(agentDir, 'agent');
}, LONG);

test('D1 an app-owned file changed on both sides: when the app syncs second, its version wins', async () => {
  app.put('source', source());
  await syncRepo(appDir, 'app', 'add source');
  await pullRepo(agentDir, 'agent');
  writeRaw(agentDir, 'sources/s1.json', source({ label: 'hand edit' }));
  await syncRepo(agentDir, 'agent', 'hand edit');
  app.put('source', source({ label: 'app edit' }));
  expect(await syncRepo(appDir, 'app', 'app edit')).toMatchObject({ pushed: true, resolved: ['sources/s1.json'] });
  expect(app.get('source', 's1')!.label).toBe('app edit');
  settled(appDir);
  await pullRepo(agentDir, 'agent');
  expect(agent.get('source', 's1')!.label).toBe('app edit');
  settled(agentDir);
}, LONG);

test('D2 when the non-owner syncs second, the owner version stays and the emptied commit is dropped', async () => {
  app.put('source', source());
  await syncRepo(appDir, 'app', 'add source');
  await pullRepo(agentDir, 'agent');
  app.put('source', source({ label: 'app edit' }));
  await syncRepo(appDir, 'app', 'app edit');
  writeRaw(agentDir, 'sources/s1.json', source({ label: 'hand edit' }));
  expect(await syncRepo(agentDir, 'agent', 'hand edit')).toMatchObject({ pushed: true, resolved: ['sources/s1.json'] });
  expect(agent.get('source', 's1')!.label).toBe('app edit');
  expect(await git(agentDir, ['log', '-1', '--format=%s'])).toBe('app edit\n');
  settled(agentDir);
}, LONG);

test('D3 an agent-owned file changed on both sides: when the agent syncs second, its version wins', async () => {
  agent.put('application', application());
  await syncRepo(agentDir, 'agent', 'add application');
  await pullRepo(appDir, 'app');
  writeRaw(appDir, 'applications/a1.json', application({ title: 'hand edit' }));
  await syncRepo(appDir, 'app', 'hand edit');
  agent.put('application', application({ title: 'agent edit' }));
  expect(await syncRepo(agentDir, 'agent', 'agent edit')).toMatchObject({ pushed: true, resolved: ['applications/a1.json'] });
  expect(agent.get('application', 'a1')!.title).toBe('agent edit');
  settled(agentDir);
}, LONG);

test('D4 the owner deleting a file wins over the other side editing it', async () => {
  app.put('source', source());
  await syncRepo(appDir, 'app', 'add source');
  await pullRepo(agentDir, 'agent');
  writeRaw(agentDir, 'sources/s1.json', source({ label: 'hand edit' }));
  await syncRepo(agentDir, 'agent', 'hand edit');
  app.delete('source', 's1');
  expect(await syncRepo(appDir, 'app', 'remove source')).toMatchObject({ pushed: true, resolved: ['sources/s1.json'] });
  expect(fs.existsSync(path.join(appDir, 'sources/s1.json'))).toBe(false);
  settled(appDir);
}, LONG);

test('D5 a file no layout row owns resolves to the app side, whichever side syncs second', async () => {
  fs.writeFileSync(path.join(appDir, 'notes.txt'), 'app\n');
  fs.writeFileSync(path.join(agentDir, 'notes.txt'), 'agent\n');
  await syncRepo(appDir, 'app', 'app notes');
  expect(await syncRepo(agentDir, 'agent', 'agent notes')).toMatchObject({ pushed: true, resolved: ['notes.txt'] });
  expect(fs.readFileSync(path.join(agentDir, 'notes.txt'), 'utf8')).toBe('app\n');
  settled(agentDir);
  fs.writeFileSync(path.join(agentDir, 'notes.txt'), 'agent 2\n');
  await syncRepo(agentDir, 'agent', 'agent 2');
  fs.writeFileSync(path.join(appDir, 'notes.txt'), 'app 2\n');
  expect(await syncRepo(appDir, 'app', 'app 2')).toMatchObject({ pushed: true, resolved: ['notes.txt'] });
  expect(fs.readFileSync(path.join(appDir, 'notes.txt'), 'utf8')).toBe('app 2\n');
  settled(appDir);
}, LONG);

test('D6 a resume with a non-ASCII name commits, pushes and reaches the other checkout', async () => {
  app.writeBlob('profile/resumes/My Résumé.pdf', new Uint8Array([1, 2, 3]));
  expect((await syncRepo(appDir, 'app', 'resume')).pushed).toBe(true);
  await pullRepo(agentDir, 'agent');
  expect(fs.readFileSync(path.join(agentDir, 'profile/resumes/My Résumé.pdf'))).toEqual(Buffer.from([1, 2, 3]));
  settled(appDir);
  settled(agentDir);
}, LONG);

test('D7 cookie-shaped files are refused and never reach the remote', async () => {
  fs.mkdirSync(path.join(appDir, 'tmp'));
  fs.writeFileSync(path.join(appDir, 'tmp/session.json'), '{"cookies":[{"name":"a","value":"b","sameSite":"Lax","httpOnly":true}]}');
  await expect(syncRepo(appDir, 'app', 'oops')).rejects.toBeInstanceOf(SecretLeakError);
  fs.writeFileSync(path.join(appDir, 'export.txt'), '# Netscape HTTP Cookie File\n.example.com\tTRUE\t/\tFALSE\t0\tsid\tabc\n');
  await expect(syncRepo(appDir, 'app', 'oops again')).rejects.toBeInstanceOf(SecretLeakError);
  const everything = sh(remote, 'log', '--all', '--name-only', '--format=');
  expect(everything).not.toContain('session.json');
  expect(everything).not.toContain('export.txt');
  expect(rebaseInProgress(appDir)).toBe(false);
}, LONG);

test('D8 pullRepo commits local changes first and never pushes', async () => {
  createCommand(app, { verb: 'run_role', target: null, payload: { role: 'finder' } });
  const before = sh(remote, 'rev-parse', 'main');
  const r = await pullRepo(appDir, 'app');
  expect(r.pushed).toBe(false);
  expect(r.committed).not.toBeNull();
  settled(appDir);
  expect(sh(remote, 'rev-parse', 'main')).toBe(before);
}, LONG);

test('D9 a command made in the app reaches the agent, and the agent result comes back', async () => {
  const c = createCommand(app, { verb: 'run_role', target: null, payload: { role: 'finder' } });
  expect((await syncRepo(appDir, 'app', 'Run now')).pushed).toBe(true);
  await pullRepo(agentDir, 'agent');
  expect(queuedCommands(agent).map((q) => q.id)).toEqual([c.id]);
  finishCommand(agent, c.id, 'done', 'ran finder');
  await syncRepo(agentDir, 'agent', 'agent run');
  await pullRepo(appDir, 'app');
  expect(app.get('command', c.id)!.state).toBe('done');
  expect(await syncRepo(appDir, 'app', 'nothing new')).toMatchObject({ committed: null, pushed: true, resolved: [] });
}, LONG);

test('D10 a fresh private repo has the format version, three starting lanes, no sources and a cookie-safe .gitignore', () => {
  expect(app.getSingleton('meta')).toMatchObject({ schemaVersion: 1 });
  expect(app.getSingleton('lanes')!.lanes.map((l) => l.name)).toEqual(['People you owe', 'Applications waiting on you', 'One outreach']);
  expect(app.list('source').items).toEqual([]);
  expect(fs.readFileSync(path.join(appDir, '.gitignore'), 'utf8')).toContain('cookies/');
  const d = tmp('cob-init-');
  fs.writeFileSync(path.join(d, 'x.txt'), 'x');
  expect(() => initDataLayout(d)).toThrow();
});
